// THE CONTROLS, chalked on each level's curtain floor (the curtain crew, Nov 15 2026; Chikin: "we need to have directions for the controls,
// so people know what to push before they go into a game"). DATA ONLY: { keys: 'keyboard words', phone: 'touch words' }, a few short words each.
// CHECKED (CONTROLS seat, Nov 15) against main.mjs (KEY map: ↑/W jump · ↓/S duck · ←/A →/D · space · v; the touch code and the #pads
// buttons ⌁ ◆ ↓ ↑ that show on touch screens) and each level's own rules (core.mjs for the runners, modes/<level>.mjs for the rest).
// The phone words, by touchMode (main.mjs):
//   (none / 'flip') tap = ↑ · hold the left third = ↓ · two fingers = space · ◆ button = v
//   'stick'         drag = hold that arrow · two fingers = space · ◆ button = v (if the level has v)
//   'tapdrag'       drag = hold that arrow (drag up = ↑, drag down = ↓) · a quick tap = space · no ◆
// Only what the level really uses is chalked. The double jump exists on every runner; it's chalked where the level is built on it.
// Keyed by level id; a ?flag runner (ghost-runner, ghost-stairs, no-answer-runner) has its own entry.
// A line only wraps BETWEEN the · pieces (each piece's own spaces are made unbreakable below), so a phone never splits "2 / fingers".
(function () {
var CT = {
  'thursday-potato':         { keys: '↑ jump · ↓ duck · space glitch',             phone: 'tap jump · hold left: duck · 2 fingers: glitch' },
  'get-down':                { keys: '↑ hop · ↓ duck · space or ← → spin',         phone: 'tap hop · hold left: duck · 2 fingers: spin' },
  'confidently-incorrect':   { keys: '↑ jump, twice · ↓ duck · space glitch',      phone: 'tap jump · hold left: duck · 2 fingers: glitch' },
  'read-the-terms':          { keys: '↑ jump, twice · ↓ duck · space glitch · v hat', phone: 'tap jump · hold left: duck · 2 fingers: glitch · ◆ hat' },
  'between-messages':        { keys: '↑ jump · space flip on/out · v truth',        phone: 'tap jump · tap left: flip · ◆ truth' },
  'ghost-in-the-group-chat': { keys: '← → walk · ↑ hop · ↓ drop · space glitch',    phone: 'drag to move · tap: glitch' },
  'still-here':              { keys: '← → run · ↑ jump · ↓ duck · space sword',     phone: 'drag to run and jump · tap: sword' },
  'no-answer':               { keys: 'arrows: his light · space call out · v dive', phone: 'drag: his light · 2 fingers: call · ◆ dive' },
  'turn-me-off':             { keys: 'arrows walk · hold space: freeze',            phone: 'drag to walk · 2 fingers: freeze' },
  'last-lights-on':          { keys: '↑ jump · ← → in the air: spin · space: the ring', phone: 'tap jump · 2 fingers: the ring' },
  'boo-not-found':           { keys: '↑ hop · ↓ duck · space glitch',              phone: 'tap hop · hold left: duck · 2 fingers: glitch' },
  // the ?flag runners (not the default levels until Chikin approves them)
  'ghost-runner':            { keys: '↑ jump · ↓ duck · ← → spin · space glitch',   phone: 'swipe up: jump · down: duck · tap: glitch' },
  'ghost-stairs':            { keys: '← → walk · ↑ hop · ↓ drop · space glitch',    phone: 'drag to move · tap: glitch' },
  'no-answer-runner':        { keys: '↑ jump · ↓ duck · space glitch',             phone: 'tap jump · hold left: duck · 2 fingers: glitch' }
};
var keep = function (t) { return String(t).split(' · ').map(function (p) { return p.replace(/ /g, '\u00a0'); }).join('\u00a0· '); };
for (var id in CT) CT[id] = { keys: keep(CT[id].keys), phone: keep(CT[id].phone) };
window.PotatoCurtainControls = Object.assign(window.PotatoCurtainControls || {}, CT);
})();
